package lk.ac.sliit.ridelink.driver.infrastructure.security;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.*; import lk.ac.sliit.ridelink.driver.presentation.exception.ApiErrorResponse; import org.springframework.http.MediaType; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.web.access.AccessDeniedHandler; import org.springframework.stereotype.Component; import java.io.IOException; import java.time.Instant; import java.util.List;
@Component public class RestAccessDeniedHandler implements AccessDeniedHandler { private final ObjectMapper m; public RestAccessDeniedHandler(ObjectMapper m){this.m=m;} public void handle(HttpServletRequest req,HttpServletResponse res,AccessDeniedException e)throws IOException{res.setStatus(403);res.setContentType(MediaType.APPLICATION_JSON_VALUE);m.writeValue(res.getOutputStream(),new ApiErrorResponse(Instant.now(),403,"Forbidden","You do not have permission to perform this operation",req.getRequestURI(),List.of()));} }
